(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#site-nav');if(menu&&nav){menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)};nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');nav.classList.remove('is-open')}})}if(!reduce&&'IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.service-card,.steps>div,.timeline article,.service-overview,.scope-grid article,.delivery,.service-proof,.faq').forEach(el=>{el.classList.add('reveal');io.observe(el)})}const track=document.querySelector('#projects');if(track){const prev=document.querySelector('#project-prev'),next=document.querySelector('#project-next'),status=document.querySelector('#carousel-status');function update(){const cards=[...track.children];const current=cards.reduce((best,c,i)=>Math.abs(c.offsetLeft-track.offsetLeft-track.scrollLeft)<Math.abs(cards[best].offsetLeft-track.offsetLeft-track.scrollLeft)?i:best,0);status.textContent=`${cards.length?current+1:0} / ${cards.length} projects`;prev.disabled=track.scrollLeft<=2;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-3}function move(dir){track.scrollBy({left:dir*((track.firstElementChild?.getBoundingClientRect().width||track.clientWidth)+28),behavior:reduce?'instant':'smooth'})}prev.onclick=()=>move(-1);next.onclick=()=>move(1);track.addEventListener('keydown',e=>{if(e.target===track&&(e.key==='ArrowRight'||e.key==='ArrowLeft')){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});track.addEventListener('scroll',update,{passive:true});new ResizeObserver(update).observe(track);new MutationObserver(()=>{track.scrollLeft=0;update()}).observe(track,{childList:true});update()}const service=new URLSearchParams(location.search).get('service');const message=document.querySelector('#contact-message');const names={'on-page-seo':'On-Page SEO','off-page-seo':'Off-Page SEO','technical-seo':'Technical SEO'};if(message&&names[service])message.value=`I would like to discuss ${names[service]} for my website. `;})();
